struct CountingStore<S: Store> { inner: S, count: u64 }   // delegate owned as a field

impl<S: Store> Store for CountingStore<S> {               // hand-written forwarding
    fn save(&mut self, id: &str) -> Result<(), Error> {
        self.count += 1;
        self.inner.save(id)
    }
    fn load(&self, id: &str) -> Result<String, Error> { self.inner.load(id) }
}

