use delegate::delegate;

impl<S: Store> Store for CountingStore<S> {
    delegate! {
        to self.inner {
            fn save(&mut self, id: &str) -> Result<(), Error>;   // macro writes it
            #[call(size)] fn len(&self) -> usize;                // renamed forwarder
